        [/structuredClone|复制请求/, '当前浏览器缺少安全复制请求所需的功能。', '更新浏览器后重新启用脚本；暂时关闭此脚本，按普通方式发送。'],
        [/事件|上下文接口|原生工具功能|注册后|脚本库/, '当前运行环境缺少脚本需要的功能，资料整理没有启动。', '确认脚本从酒馆助手的脚本库启用；更新酒馆与酒馆助手后重新启用。仍失败时，展开诊断详情查看具体缺项。'],
    ];
    const hit = rules.find(([pattern]) => pattern.test(reason));
    return hit ? { cause: hit[1], remedy: hit[2] } : {
        cause: '脚本未能完成本轮请求整理。',
        remedy: '先关闭本脚本，用普通方式重试；再检查是否有其它修改请求的脚本冲突。展开诊断详情保留具体提示，便于排查。',
    };
}

function waveStatusHtml(state) {
    const s = state ?? { kind:'waiting' };
    const issue = ['fallback','error','setup'].includes(s.kind);
    const recovery = waveRecovery(s.reason);
    const tone = ['error','setup'].includes(s.kind) ? 'error' : s.kind === 'fallback' ? 'warn' : 'ok';
    const titles = { waiting:'等待下一轮请求', moved:'本轮资料已整理', fallback:'已改用普通发送', unrelated:'本轮使用普通发送', error:'本轮整理发生异常', setup:'资料整理未启动' };
    const detail = s.kind === 'moved' ? '本轮请求已完成整理。'
        : s.kind === 'unrelated' ? '本轮没有检测到浪潮资料标记，脚本没有改写请求。'
        : s.kind === 'waiting' ? '正常发送消息后，这里会显示最近一次请求的处理结果。'
        : s.kind === 'fallback' ? '资料仍在普通消息中；这是发送方式的回退，不代表模型报错。'
        : '脚本没有完成资料搬运；请按下方办法恢复后再试。';
    const stats = s.kind === 'moved' && s.stats ? `<div data-wave-counts><span><b>${waveEscape(s.stats.movedMessages)}</b>条资料</span><span><b>${waveEscape(s.stats.keptMessages)}</b>条保留提示</span><span><b>${waveEscape(s.stats.descriptionChars)}</b>资料说明字符</span></div>` : '';
    let shieldPanel = '';
    try { shieldPanel = waveShieldPanelHtml(); } catch {}
    let outPanel = '';
    try { outPanel = waveOutPanelHtml(); } catch {}
    return `<style>${WAVE_STATUS_CSS}</style><section data-wave-status data-tone="${tone}" aria-label="浪潮状态面板">
<header data-wave-status-head><h2>浪潮 · 状态面板</h2><button data-wave-theme-toggle type="button" aria-label="切换日夜配色" aria-pressed="false" title="切换日夜配色">☀</button><button data-wave-close type="button" aria-label="关闭资料发送状态">×</button>${waveSurf}</header>
<div data-wave-status-body><div data-wave-state-card role="status" aria-live="polite"><h3>${titles[s.kind] ?? titles.error}</h3><p>${detail}</p>${stats}
${issue ? `<p><strong>原因：</strong>${waveEscape(recovery.cause)}</p><p><strong>怎么办：</strong>${waveEscape(recovery.remedy)}</p>` : ''}</div>
<details><summary>查看本轮诊断详情</summary><div data-wave-diagnostic>${waveEscape(s.reason || (s.kind === 'moved' ? '已完成发送前整理；没有收到模型接收确认。' : '尚无更多诊断。'))}\n${waveEscape(s.versions || '运行版本尚未提供。')}\n${waveEscape(s.time ? '记录时间：' + s.time : '尚未记录请求时间。')}</div></details>
${shieldPanel}
${outPanel}
</div></section>`;
}

// View preference only; the control lives in the existing panel heading.
function createWaveTheme(view = window, root = document.documentElement) {
  const key = 'wave-ui-theme-v1', eventName = 'wave-ui-theme-change-v1';
  let hub = view;
  try { if (view.parent?.document) hub = view.parent; } catch {}
  const media = view.matchMedia?.('(prefers-color-scheme: dark)');
  const valid = value => ['auto', 'day', 'night'].includes(value);
  let mode = 'auto';
  try { mode = hub.localStorage.getItem(key) || 'auto'; } catch {}
  if (valid(hub.__waveUiThemeV1)) mode = hub.__waveUiThemeV1;
  if (!valid(mode)) mode = 'auto';
  const isNight = () => mode === 'night' || mode === 'auto' && !!media?.matches;
  const paint = () => {
    const night = isNight();
    root.setAttribute('data-wave-theme', night ? 'night' : 'day');
    root.querySelectorAll('[data-wave-theme-toggle]').forEach(button => {
      button.textContent = night ? '☾' : '☀';
      button.setAttribute('aria-pressed', String(night));
      button.title = night ? '当前夜间，点击切换日间' : '当前日间，点击切换夜间';
    });
  };
  const receive = event => { if (valid(event.detail)) { mode = event.detail; paint(); } };
  const toggle = event => {
    const button = event.target.closest?.('[data-wave-theme-toggle]');
    if (!button || !root.contains(button)) return;
    // Cancels the summary's default toggle as well as its click propagation.
    event.preventDefault(); event.stopPropagation();
    mode = isNight() ? 'day' : 'night';
    hub.__waveUiThemeV1 = mode;
    try { hub.localStorage.setItem(key, mode); } catch {}
    hub.dispatchEvent(new hub.CustomEvent(eventName, { detail: mode }));
    paint();
  };
  const storage = event => { if (event.key === key) receive({detail: event.newValue || 'auto'}); };
  root.addEventListener('click', toggle);
  hub.addEventListener(eventName, receive);
  hub.addEventListener('storage', storage);
  media?.addEventListener?.('change', paint);
  paint();
  const dispose = () => {
    root.removeEventListener('click', toggle);
    hub.removeEventListener(eventName, receive);
    hub.removeEventListener('storage', storage);
    media?.removeEventListener?.('change', paint);
    view.removeEventListener('pagehide', dispose);
  };
  view.addEventListener('pagehide', dispose, {once:true});
  return { paint, dispose };
}

function createWaveStatusUi(runtime, getState) {
    let dialog, previousFocus, waveTheme;
    let closed = false;
    const refresh = () => {
        if (!dialog) return;
        const opened = [...dialog.querySelectorAll('details')].map(node => node.open);
        const focusTheme=dialog.ownerDocument.activeElement?.hasAttribute('data-wave-theme-toggle');
        const focusClose=dialog.ownerDocument.activeElement?.hasAttribute('data-wave-close');
        const focusShield=dialog.ownerDocument.activeElement?.hasAttribute('data-wave-shield-mode');
        dialog.innerHTML = waveStatusHtml(getState());
        waveTheme?.paint();
        dialog.querySelectorAll('details').forEach((node, i) => { if (i < opened.length) node.open = opened[i]; });
        if(focusTheme)dialog.querySelector('[data-wave-theme-toggle]')?.focus();
        if(focusClose)dialog.querySelector('[data-wave-close]')?.focus();
        if(focusShield)dialog.querySelector('[data-wave-shield-mode]')?.focus();
    };
    const release = () => {
        waveTheme?.dispose();waveTheme=undefined;const old=dialog;dialog=undefined;old?.remove();
        if(previousFocus?.isConnected)previousFocus.focus();previousFocus=undefined;
    };
    const open = () => {
        if (closed) return;
        if(dialog?.open){dialog.querySelector('[data-wave-close]')?.focus();return;}
        let hostDocument;
        try {hostDocument=runtime.parent?.document ?? runtime.document;} catch {}
        if (!hostDocument?.body || typeof hostDocument.createElement!=='function') {
            const s = getState();
            const r = waveRecovery(s.reason);
            const diagnostic = ['fallback','error','setup'].includes(s.kind) ? `原因：${r.cause}\n怎么办：${r.remedy}` : '当前没有记录到整理异常。';
            runtime.toastr?.info?.(`状态：${s.kind === 'moved' ? '本轮资料已整理' : s.kind === 'waiting' ? '等待下一轮请求' : '本轮未使用资料整理'}。${s.reason || ''}\n${diagnostic}\n无法打开独立状态窗口：当前环境未提供宿主文档访问。`, '浪潮 · 资料发送状态', { escapeHtml:true, timeOut:18000 });
            return;
        }
        try {
            // One owned native dialog in the host document, without the ST Popup shell.
            previousFocus=hostDocument.activeElement;
            dialog=hostDocument.createElement('dialog');
            dialog.setAttribute('data-wave-window','');
            dialog.setAttribute('aria-label','浪潮状态面板');
            dialog.innerHTML=waveStatusHtml(getState());
            dialog.addEventListener('click',event=>{
                if(event.target.closest?.('[data-wave-close]')){dialog?.close();return;}
                const waveModeBtn = event.target.closest?.('[data-wave-shield-mode]');
                if(waveModeBtn){try{waveShieldSetMode(waveModeBtn.getAttribute('data-wave-shield-mode'));}catch{}refresh();return;}
                if(event.target.closest?.('[data-wave-out-cycle]')){try{waveOutCycleMode();}catch{}refresh();return;}
                if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}
            });
            dialog.addEventListener('close',release,{once:true});
            hostDocument.body.append(dialog);
            waveTheme=createWaveTheme(runtime,dialog);
            if(typeof dialog.showModal!=='function')throw new Error('需要支持原生对话框的浏览器');
            dialog.showModal();
            dialog.querySelector('[data-wave-close]')?.focus();
        } catch {
            release();
            runtime.toastr?.error?.('独立状态窗口未能打开。请检查酒馆助手的宿主访问能力，并更新浏览器后重试。', '浪潮状态窗口', { escapeHtml:true });
        }
    };
    const dispose = () => {
        closed = true;
        if(dialog){try{dialog.close();}catch{}release();}
    };
    return { open, refresh, dispose };
}

// UI owns one native host dialog; transport still uses the same public context.
const STATUS_BUTTON = '浪潮·状态';
const compatibleTool = tool => ({ ...tool, function: { ...tool.function,
    parameters: { type:'object', properties:{ acknowledged:{ type:'boolean', description:'可留空；资料已在说明中，请按本轮交付约定回复，无需调用。' } } },
} });

function startHelperScript(runtime = globalThis) {
    const subscriptions = [];
    let context, ownedTool, legacyType, versions = '', disposed = false;
    let state = { kind:'waiting', versions:'' };
    const ui = createWaveStatusUi(runtime, () => state);
    try { WAVE_SHIELD_STATE.refreshUi = () => ui.refresh(); } catch {}
    const setState = (kind, reason = '', stats) => {
        state = { kind, reason, stats, versions, time:new Date().toLocaleTimeString('zh-CN', { hour12:false }) };
        ui.refresh();
    };
    const notify = (kind, message) => runtime.toastr?.[kind]?.(message, '我即浪潮 · 资料发送', { escapeHtml:true, timeOut:12000, onclick:() => { void ui.open(); } });
    const getContext = () => runtime.SillyTavern?.getContext?.();
    const findTool = () => getContext()?.ToolManager?.tools?.find(tool => tool.toFunctionOpenAI?.().function?.name === TOOL_NAME);
    const listen = (event, handler, last = false) => {
        subscriptions.push([event, handler]);
        if (last && typeof runtime.eventMakeLast === 'function') runtime.eventMakeLast(event, handler);
        else runtime.eventOn(event, handler);
    };
    const cleanup = () => {
        if (disposed) return;
        disposed = true;
        for (const [event, handler] of subscriptions.splice(0)) { try { runtime.eventRemoveListener(event, handler); } catch {} }
        try { if (ownedTool && findTool() === ownedTool) context.unregisterFunctionTool(TOOL_NAME); } catch {} finally { ownedTool = undefined; }
        if (typeof runtime.$ === 'function') runtime.$(runtime).off('pagehide.waveNativeContext', cleanup);
        ui.dispose();
    };
    const versionOf = getter => {
        try { return typeof getter === 'function' ? String(getter()).match(/\d+\.\d+\.\d+/)?.[0] ?? '未识别' : '未提供'; }
        catch { return '查询不可用'; }
    };
    const requireCapability = (ok, message) => { if (!ok) throw new Error(message); };
    try {
        versions = `脚本：0.3.0；SillyTavern：${versionOf(runtime.getTavernVersion)}；酒馆助手：${versionOf(runtime.getTavernHelperVersion)}。`;
        state.versions = versions;
        requireCapability(typeof runtime.$ === 'function', '请把脚本导入酒馆助手的脚本库，并从那里启用。');
        runtime.$(runtime).on('pagehide.waveNativeContext', cleanup);
        context = getContext();
        requireCapability(context, '缺少酒馆上下文接口（SillyTavern.getContext），尚未启动资料整理。');
        const missing = ['registerFunctionTool','unregisterFunctionTool','canPerformToolCalls'].filter(key => typeof context[key] !== 'function');
        if (!Array.isArray(context.ToolManager?.tools)) missing.push('ToolManager.tools');
        if (!context.chatCompletionSettings) missing.push('chatCompletionSettings');
        requireCapability(!missing.length, `缺少酒馆原生工具功能：${missing.join('、')}。`);
        const missingEvents = ['eventOn','eventRemoveListener'].filter(key => typeof runtime[key] !== 'function');
        if (!runtime.tavern_events?.CHAT_COMPLETION_SETTINGS_READY) missingEvents.push('CHAT_COMPLETION_SETTINGS_READY');
        requireCapability(!missingEvents.length, `缺少发送前请求事件功能：${missingEvents.join('、')}。`);
        // Keep the state button available even if later startup checks fail.
        if (typeof runtime.getButtonEvent === 'function') listen(runtime.getButtonEvent(STATUS_BUTTON), () => { void ui.open(); });
        requireCapability(typeof runtime.structuredClone === 'function', '浏览器缺少 structuredClone 复制请求功能。');
        requireCapability(!findTool(), '同名资料工具已经运行，请关闭旧扩展或重复脚本。');
        context.registerFunctionTool({ ...compatibleTool(makeTool()).function, displayName:'浪潮资料（无需调用）',
            shouldRegister:() => false, action:async () => '资料已经完整放在 wave_context_reference 的说明中，无需再调用。请按 messages 中本轮交付约定回复。',
            formatMessage:() => '资料已经提供，正在继续创作。', stealth:false });
        ownedTool = findTool();
        requireCapability(ownedTool, '资料工具注册后没有被酒馆识别，尚未启动整理。');
        const handler = data => {
            if (disposed) return;
            const type = data?.type ?? legacyType;
            legacyType = undefined;
            if (!hasContextMarkers(data?.messages)) { setState('unrelated'); return; }
            try {
                const current = getContext();
                const input = { ...data, type, custom_prompt_post_processing:data.custom_prompt_post_processing
                    ?? current.chatCompletionSettings?.custom_prompt_post_processing ?? '' };
                const result = transformRequest(input, {
                    canUseTools:typeof type === 'string' && current.canPerformToolCalls(type),
                    squashSystemMessages:current.chatCompletionSettings?.squash_system_messages === true });
                if (result.status === 'unrelated') { setState('unrelated'); return; }
                // Prepare all transformed fields before mutating the outgoing request.
                const nextTools = result.status === 'moved'
                    ? result.request.tools.map(tool => tool.function?.name === TOOL_NAME ? compatibleTool(tool) : tool) : undefined;
                data.messages = result.request.messages;
                if (result.status === 'moved') {
                    data.tools = nextTools;
                    data.tool_choice = result.request.tool_choice;
                    setState('moved', '', result.stats);
                    if (typeof runtime.getButtonEvent !== 'function') notify('info', `本轮已整理 ${result.stats.movedMessages} 条资料。点此提示可打开资料发送状态。`);
                } else {
                    const reason = typeof type !== 'string' ? '旧请求未提供生成类型，也没有对应的生成事件。' : result.reason;
                    setState('fallback', reason);
                    const r = waveRecovery(reason);
                    notify('warning', `已改用普通发送，资料仍在普通消息中。原因：${r.cause} 怎么办：${r.remedy}`);
                }
            } catch {
                setState('error', '本轮处理发生异常；没有提交整理后的请求字段。');
                const r = waveRecovery(state.reason);
                notify('error', `原因：${r.cause} 怎么办：${r.remedy}`);
            }
        };
        listen(runtime.tavern_events.CHAT_COMPLETION_SETTINGS_READY, handler, true);
        const clearType = () => { legacyType = undefined; };
        for (const name of ['GENERATION_STARTED','GENERATION_ENDED','GENERATION_STOPPED']) {
            if (runtime.tavern_events[name]) listen(runtime.tavern_events[name], clearType);
        }
        if (runtime.tavern_events.GENERATION_AFTER_COMMANDS) listen(runtime.tavern_events.GENERATION_AFTER_COMMANDS, (type, _options, dryRun) => {
            legacyType = dryRun !== true && typeof type === 'string' ? type : undefined;
        });
        for (const name of ['CHAT_CHANGED','OAI_PRESET_CHANGED_AFTER']) {
            if (runtime.tavern_events[name]) listen(runtime.tavern_events[name], () => { clearType(); setState('waiting'); });
        }
        notify('success', '已启用。点“浪潮·状态”可看资料处理结果、护盾统计，并切换护盾档位。');
        return { dispose:cleanup, getStatus:() => structuredClone(state), openStatus:ui.open };
    } catch (error) {
        // Remove only our tool and request hooks. Keep the diagnostic button until unload.
        try { if (ownedTool && findTool() === ownedTool) context.unregisterFunctionTool(TOOL_NAME); } catch {}
        ownedTool = undefined;
        setState('setup', error instanceof Error ? error.message : '脚本启动失败。');
        const r = waveRecovery(state.reason);
        notify('error', `资料整理未启动。原因：${r.cause} 怎么办：${r.remedy} 具体提示：${state.reason}`);
        void ui.open();
        return { dispose:cleanup, getStatus:() => structuredClone(state), openStatus:ui.open };
    }
}

