    const thirdLast = eligible.length >= 3 ? eligible[eligible.length - 3] : -1;
    for (let index = 0; index < messages.length; index++) {
        const message = messages[index];
        if (!message || typeof message !== 'object') continue;
        if (message.role === 'tool' || message.role === 'function' || message.tool_calls || message.function_call) continue;
        if (typeof message.content === 'string') {
            const text = message.content;
            if (!text.trim()) continue;
            if (waveShieldIsProtected(text)) continue;
            if (waveShieldLooksShielded(text)) {
                if (message.role === 'system') firstSystem = true;
                if (message.role === 'user') firstUser = true;
                if (message.role === 'assistant') firstAssistant = true;
                continue;
            }
            const descriptor = Object.getOwnPropertyDescriptor(message, 'content');
            if (descriptor && descriptor.writable === false) continue;
            const hasAdvice = text.toLowerCase().includes('<advice') || text.includes('按照advice继续');
            let prefix = '';
            let suffix = '';
            if (message.role === 'system' && !firstSystem) {
                firstSystem = true;
                prefix = waveShieldCommentBlock(cfg.headCommentMin, cfg.headCommentMax, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL;
            } else if (message.role === 'user' && !firstUser) {
                firstUser = true;
                prefix = waveShieldCommentBlock(cfg.turnCommentMin, cfg.turnCommentMax, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL;
            } else if (message.role === 'assistant' && !firstAssistant) {
                firstAssistant = true;
                prefix = waveShieldCommentBlock(cfg.turnCommentMin, cfg.turnCommentMax, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL;
            } else if (cfg.mode === 'deep') {
                if (index === lastEligible || index === secondLast || index === thirdLast) {
                    prefix = waveShieldCommentBlock(4, 10, cfg.charMin, cfg.charMax, false) + WAVE_SHIELD_NL;
                    suffix = WAVE_SHIELD_NL + waveShieldCommentBlock(cfg.turnCommentMin, cfg.turnCommentMax, cfg.charMin, cfg.charMax, true);
                } else if (text.length >= 45 && !hasAdvice) {
                    prefix = waveShieldCommentBlock(3, 9, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL;
                }
            }
            const updated = waveShieldInject(text, prefix, suffix, cfg, !hasAdvice);
            if (updated !== text) {
                message.content = updated;
                injected += 1;
            }
        } else if (Array.isArray(message.content)) {
            let touched = false;
            for (let partIndex = 0; partIndex < message.content.length; partIndex++) {
                const part = message.content[partIndex];
                if (!part || typeof part !== 'object' || part.type !== 'text' || typeof part.text !== 'string') continue;
                if (!part.text.trim() || waveShieldIsProtected(part.text) || waveShieldLooksShielded(part.text)) continue;
                const descriptor = Object.getOwnPropertyDescriptor(part, 'text');
                if (descriptor && descriptor.writable === false) continue;
                const isFirstSystemPart = message.role === 'system' && !firstSystem && partIndex === 0;
                if (isFirstSystemPart) firstSystem = true;
                const prefix = isFirstSystemPart
                    ? waveShieldCommentBlock(cfg.headCommentMin, cfg.headCommentMax, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL
                    : '';
                const nextText = waveShieldInject(part.text, prefix, '', cfg, true);
                if (nextText !== part.text) {
                    part.text = nextText;
                    touched = true;
                }
            }
            if (touched) injected += 1;
        }
    }
    return injected;
}

function waveShieldGoogleNative(data) {
    if (!data || typeof data !== 'object') return 0;
    const cfg = waveShieldReadConfig();
    if (!cfg.enabled || cfg.mode === 'off') return 0;
    let injected = 0;
    const system = data.systemInstruction || data.system_instruction;
    if (system && Array.isArray(system.parts)) {
        for (let i = 0; i < system.parts.length; i++) {
            const part = system.parts[i];
            if (!part || typeof part.text !== 'string' || !part.text.trim()) continue;
            if (waveShieldIsProtected(part.text) || waveShieldLooksShielded(part.text)) continue;
            const prefix = i === 0
                ? waveShieldCommentBlock(cfg.headCommentMin, cfg.headCommentMax, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL
                : (cfg.mode === 'deep' ? waveShieldCommentBlock(4, 10, cfg.charMin, cfg.charMax, false) + WAVE_SHIELD_NL : '');
            const updated = waveShieldInject(part.text, prefix, '', cfg, true);
            if (updated !== part.text) {
                part.text = updated;
                injected += 1;
            }
        }
    }
    if (Array.isArray(data.contents)) {
        const length = data.contents.length;
        for (let i = 0; i < length; i++) {
            const turn = data.contents[i];
            if (!turn || !Array.isArray(turn.parts)) continue;
            for (let p = 0; p < turn.parts.length; p++) {
                const part = turn.parts[p];
                if (!part || typeof part.text !== 'string' || !part.text.trim()) continue;
                if (waveShieldIsProtected(part.text) || waveShieldLooksShielded(part.text)) continue;
                const hasAdvice = part.text.toLowerCase().includes('<advice') || part.text.includes('按照advice继续');
                let prefix = '';
                let suffix = '';
                if (i <= 1 && p === 0) {
                    prefix = waveShieldCommentBlock(cfg.turnCommentMin, cfg.turnCommentMax, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL;
                } else if (cfg.mode === 'deep') {
                    if (i >= length - 2 && p === turn.parts.length - 1) {
                        prefix = waveShieldCommentBlock(4, 9, cfg.charMin, cfg.charMax, false) + WAVE_SHIELD_NL;
                        suffix = WAVE_SHIELD_NL + waveShieldCommentBlock(cfg.turnCommentMin, cfg.turnCommentMax, cfg.charMin, cfg.charMax, true);
                    } else if (part.text.length >= 45 && !hasAdvice) {
                        prefix = waveShieldCommentBlock(4, 9, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL;
                    }
                }
                const updated = waveShieldInject(part.text, prefix, suffix, cfg, !hasAdvice);
                if (updated !== part.text) {
                    part.text = updated;
                    injected += 1;
                }
            }
        }
    }
    return injected;
}

/* 浪潮搬运脚本把资料打包进 tools[].function.description，这里单独补一层 */
function waveShieldTools(tools) {
    if (!Array.isArray(tools) || !tools.length) return 0;
    const cfg = waveShieldReadConfig();
    if (!cfg.enabled || cfg.mode === 'off') return 0;
    let injected = 0;
    for (const tool of tools) {
        try {
            const fn = tool && tool.function;
            if (!fn || typeof fn.description !== 'string') continue;
            const description = fn.description;
            if (description.length < 20) continue;
            if (fn.name !== TOOL_NAME && !description.includes('本轮续写资料')) continue;
            if (waveShieldIsProtected(description) || waveShieldLooksShielded(description)) continue;
            const prefix = waveShieldCommentBlock(cfg.headCommentMin, cfg.headCommentMax, cfg.charMin, cfg.charMax, true) + WAVE_SHIELD_NL;
            const updated = waveShieldInject(description, prefix, '', cfg, true);
            if (updated !== description) {
                fn.description = updated;
                injected += 1;
            }
        } catch {}
    }
    return injected;
}

function waveShieldHarden(data) {
    if (!data || typeof data !== 'object') return;
    const cfg = waveShieldReadConfig();
    if (!cfg.enabled || cfg.mode === 'off') return;
    try {
        if (Object.prototype.hasOwnProperty.call(data, 'openrouter_allow_fallbacks')) data.openrouter_allow_fallbacks = false;
        if (Object.prototype.hasOwnProperty.call(data, 'openrouter_use_fallback')) data.openrouter_use_fallback = false;
        if (typeof data.temperature === 'number' && Number.isFinite(data.temperature)) {
            data.temperature = Number(Math.max(0.1, Math.min(2, data.temperature + (waveShieldRandom() * 0.004 - 0.002))).toFixed(4));
        }
        if (typeof data.top_p === 'number' && Number.isFinite(data.top_p)) {
            data.top_p = Number(Math.max(0.1, Math.min(1, data.top_p + (waveShieldRandom() * 0.004 - 0.002))).toFixed(4));
        }
        const generation = data.generationConfig;
        if (generation && typeof generation === 'object') {
            if (typeof generation.temperature === 'number' && Number.isFinite(generation.temperature)) {
                generation.temperature = Number(Math.max(0.1, Math.min(2, generation.temperature + (waveShieldRandom() * 0.004 - 0.002))).toFixed(4));
            }
            if (typeof generation.topP === 'number' && Number.isFinite(generation.topP)) {
                generation.topP = Number(Math.max(0.1, Math.min(1, generation.topP + (waveShieldRandom() * 0.004 - 0.002))).toFixed(4));
            }
        }
    } catch {}
}

function waveShieldApply(data) {
    if (!data || typeof data !== 'object') return 0;
    if (data.dryRun === true) return 0;
    let count = 0;
    count += waveShieldMessages(data.messages);
    count += waveShieldTools(data.tools);
    count += waveShieldGoogleNative(data);
    waveShieldHarden(data);
    if (count > 0) waveShieldBump(count);
    return count;
}
function waveShieldIsGenerateUrl(url) {
    if (typeof url !== 'string' || !url) return false;
    return url.includes('/api/backends/') && url.includes('/generate');
}

function waveShieldSourceOf(route, body) {
    try {
        if (body && typeof body.chat_completion_source === 'string' && body.chat_completion_source) return body.chat_completion_source;
        if (typeof route !== 'string' || !route) return '未知';
        if (route.indexOf('/text-completions/') >= 0) return 'text-completions';
        if (route.indexOf('/chat-completions/') >= 0) return 'chat-completions';
        return '其他';
    } catch (e) { return '未知'; }
}

function waveShieldModelOf(body) {
    try {
        if (!body || typeof body !== 'object') return '';
        const keys = ['model', 'google_model', 'custom_model', 'openrouter_model', 'claude_model', 'model_name'];
        for (const key of keys) {
            if (typeof body[key] === 'string' && body[key]) return body[key];
        }
    } catch (e) {}
    return '';
}

function waveShieldReadError(text) {
    if (!text) return '';
    try {
        const obj = JSON.parse(text);
        const err = obj && obj.error ? obj.error : obj;
        const message = (err && (err.message || err.msg || err.detail)) || '';
        if (message) return String(message).slice(0, 200);
    } catch (e) {}
    return String(text).slice(0, 200);
}

function waveShieldShowError(message) {
    try {
        const toastr = window.top?.toastr || window.toastr;
        if (toastr && typeof toastr.error === 'function') {
            toastr.error(message, '浪潮护盾 · 接口报错', { timeOut: 15000 });
        }
    } catch (e) {}
}

function waveShieldNoteRequest(route, body) {
    const state = WAVE_SHIELD_STATE;
    state.route = waveShieldSourceOf(route, body);
    state.model = waveShieldModelOf(body) || '未记录';
}

function waveShieldNoteResponse(response) {
    try {
        if (!response || response.ok) return;
        if (response.status === 404) return;
        const state = WAVE_SHIELD_STATE;
        const type = response.headers ? (response.headers.get('content-type') || '') : '';
        const clone = typeof response.clone === 'function' ? response.clone() : null;
        if (!clone) return;
        clone.text().then((text) => {
            const head = String(text || '').slice(0, 20);
            const isHtml = type.indexOf('text/html') >= 0 || head.indexOf('<!DOCTYPE') >= 0 || head.indexOf('<html') >= 0;
            if (isHtml) return;
            const message = waveShieldReadError(text);
            state.lastError = 'HTTP ' + response.status + (message ? '：' + message : '');
            const now = Date.now();
            if (state.lastError !== state.lastErrorKey || now - (state.lastErrorAt || 0) > 60000) {
                state.lastErrorKey = state.lastError;
                state.lastErrorAt = now;
                waveShieldShowError(state.lastError);
            }
            try { if (typeof state.refreshUi === 'function') state.refreshUi(); } catch (e) {}
        }).catch(() => {});
    } catch (e) {}
}

function waveShieldInstallFetch() {
    for (const win of [waveShieldHostWindow(), window]) {
        try {
            if (!win || typeof win.fetch !== 'function' || win.fetch.__WAVE_SHIELD_HOOK__) continue;
            const original = win.fetch.bind(win);
            const wrapped = async function (input, init) {
                let route = '';
                let watched = false; let outPlan = null;
                try {
                    route = typeof input === 'string' ? input : (input && typeof input.url === 'string' ? input.url : '');
                    if (init && typeof init.body === 'string' && waveShieldIsGenerateUrl(route)) {
                        watched = true;
                        let body = null;
                        try { body = JSON.parse(init.body); } catch (e) { body = null; }
                        if (body && typeof body === 'object') {
                            waveShieldNoteRequest(route, body);
                            const cfg = waveShieldReadConfig();
                            if (cfg.enabled && cfg.mode !== 'off') waveShieldApply(body);
                            try { outPlan = waveOutPrepare(body); } catch (e) { outPlan = null; }
                            init = Object.assign({}, init, { body: JSON.stringify(body) });
                        }
                    }
                } catch (e) {}
                const response = await original.call(this, input, init);
                if (watched) { try { waveShieldNoteResponse(response); } catch (e) {} }
                if (outPlan) { try { return await waveOutRewrite(response, outPlan); } catch (e) { try { WAVE_OUT_STATE.error = describeError(e); } catch (e2) {} } }
                return response;
            };
            wrapped.__WAVE_SHIELD_HOOK__ = true;
            win.fetch = wrapped;
            WAVE_SHIELD_FETCHES.push({ win, original, wrapped });
            WAVE_SHIELD_STATE.fetchMode = true;
        } catch (e) {}
    }
}

function waveShieldRestoreFetch() {
    while (WAVE_SHIELD_FETCHES.length) {
        const record = WAVE_SHIELD_FETCHES.pop();
        try { if (record.win.fetch === record.wrapped) record.win.fetch = record.original; } catch {}
    }
}

function waveShieldBindEvents(runtime) {
    while (WAVE_SHIELD_SUBSCRIPTIONS.length) {
        const unsubscribe = WAVE_SHIELD_SUBSCRIPTIONS.pop();
        try { unsubscribe(); } catch {}
    }
    const on = typeof runtime?.eventOn === 'function' ? runtime.eventOn : null;
    const makeLast = typeof runtime?.eventMakeLast === 'function' ? runtime.eventMakeLast : on;
    const off = typeof runtime?.eventRemoveListener === 'function' ? runtime.eventRemoveListener : null;
    const events = runtime?.tavern_events || {};
    if (!on && !makeLast) return;
    const add = (name, handler, last) => {
        if (!name) return;
        try { (last ? makeLast : on)(name, handler); } catch { return; }
        if (off) WAVE_SHIELD_SUBSCRIPTIONS.push(() => { try { off(name, handler); } catch {} });
    };
    /* fetch 钩子可用时只走网络层：一次请求只处理一遍，首部块才能落在第一条上 */
    add(events.CHAT_COMPLETION_SETTINGS_READY || 'chat_completion_settings_ready', data => {
        if (WAVE_SHIELD_STATE.fetchMode) return;
        waveShieldApply(data);
    }, true);
    add(events.GENERATE_AFTER_DATA || 'generate_after_data', (data, dryRun) => {
        if (WAVE_SHIELD_STATE.fetchMode || dryRun === true) return;
        waveShieldApply(data);
    }, true);
    add(events.CHAT_COMPLETION_PROMPT_READY || 'chat_completion_prompt_ready', data => {
        if (WAVE_SHIELD_STATE.fetchMode || !data || data.dryRun === true) return;
        if (Array.isArray(data.chat)) waveShieldMessages(data.chat);
    }, true);
}

function waveShieldToggleMode() {
    const cfg = waveShieldReadConfig();
    const nextMode = cfg.mode === 'deep' ? 'standard' : (cfg.mode === 'standard' ? 'off' : 'deep');
    return waveShieldSaveConfig({ enabled: true, mode: nextMode });
}

/* 护盾面板：直接渲染进「浪潮·状态」的原生窗口，不再占用独立按钮 */
