function waveShieldDisposeLegacy() {
    for (const win of [waveShieldHostWindow(), window]) {
        for (const slot of [WAVE_SHIELD_SLOT, ...WAVE_SHIELD_LEGACY_SLOTS]) {
            try {
                const existing = win && win[slot];
                if (existing && typeof existing.dispose === 'function') existing.dispose();
            } catch {}
        }
    }
}

function waveShieldDispose() {
    while (WAVE_SHIELD_TIMERS.length) {
        try { clearTimeout(WAVE_SHIELD_TIMERS.pop()); } catch {}
    }
    while (WAVE_SHIELD_SUBSCRIPTIONS.length) {
        const unsubscribe = WAVE_SHIELD_SUBSCRIPTIONS.pop();
        try { unsubscribe(); } catch {}
    }
    waveShieldRestoreFetch();
}

function waveShieldAttach(runtime = globalThis) {
    if (WAVE_SHIELD_STATE.attached) return;
    WAVE_SHIELD_STATE.attached = true;
    try { waveShieldDisposeLegacy(); } catch {}
    waveShieldInstallFetch();
    waveShieldBindEvents(runtime);
    for (const delay of [800, 2400]) {
        WAVE_SHIELD_TIMERS.push(setTimeout(() => {
            try {
                waveShieldInstallFetch();
                waveShieldBindEvents(runtime);
            } catch {}
        }, delay));
    }
    try {
        const win = waveShieldHostWindow();
        win[WAVE_SHIELD_SLOT] = {
            version: WAVE_SHIELD_VERSION,
            state: WAVE_SHIELD_STATE,
            dispose: waveShieldDispose,
            readConfig: waveShieldReadConfig,
            saveConfig: waveShieldSaveConfig,
            applyToRequest: waveShieldApply,
        };
        win.addEventListener('pagehide', waveShieldDispose, { once: true });
    } catch {}
}


/* ===================================================================
 * 输出通道（防截断）
 * 两种走法：
 *   原生 —— 请求里挂 actual_content 工具，正文写进工具参数，回包再还原（默认）
 *   文本 —— 渠道不支持原生工具时，让模型把正文写在两个标记之间，由本脚本
 *           自己扫出来还原，全程不依赖任何工具能力
 * 移植自「防截断（S喵 昆仑）」的输出防截断部分；不含全防截断与独立悬浮窗。
 * =================================================================== */

const WAVE_OUT_TOOL = 'actual_content';
const WAVE_OUT_STORAGE_KEY = 'wave-out-channel-v1';
const TOOL_DESCRIPTION = '浪潮，把这一轮的全部输出都写到这里';
const TOOL_PREFIX = 'emit_complete_response_';
const WAVE_OUT_OPEN = '<wave_delivery>';
const WAVE_OUT_CLOSE = '</wave_delivery>';
const WAVE_OUT_MODES = ['auto', 'native', 'text', 'off'];
const WAVE_OUT_STATE = {
    mode: 'auto', loaded: false, turns: 0, lastChars: 0,
    lastTime: '', lastMode: '', skip: '', error: '',
};

const Logger = { info() {}, warn() {}, error() {}, log() {} };
const adapter = { getCurrentModel: () => '' };
const AntiTruncationDebugger = {
    log() {}, recordChunk() {}, recordToolCall() {}, startTrace() {},
    recordStats(stats) { waveOutNote(stats, ''); },
};
const FloatingMonitor = {
    append() {}, set() {}, startSession() {}, finishSession() {}, setMode() {},
};

function describeError(error) {
    try { return String((error && (error.message || error)) || '未知错误'); } catch (e) { return '未知错误'; }
}

function waveOutReadConfig() {
    if (!WAVE_OUT_STATE.loaded) {
        WAVE_OUT_STATE.loaded = true;
        try {
            const store = waveShieldStorage();
            const raw = store ? store.getItem(WAVE_OUT_STORAGE_KEY) : null;
            const parsed = raw ? JSON.parse(raw) : {};
            const mode = parsed && parsed.mode;
            if (WAVE_OUT_MODES.includes(mode)) WAVE_OUT_STATE.mode = mode;
        } catch (e) {}
    }
    return { mode: WAVE_OUT_STATE.mode };
}

function waveOutSaveConfig(partial) {
    if (partial && WAVE_OUT_MODES.includes(partial.mode)) WAVE_OUT_STATE.mode = partial.mode;
    WAVE_OUT_STATE.loaded = true;
    try {
        const store = waveShieldStorage();
        if (store) store.setItem(WAVE_OUT_STORAGE_KEY, JSON.stringify({ mode: WAVE_OUT_STATE.mode }));
    } catch (e) {}
    return { mode: WAVE_OUT_STATE.mode };
}

function waveOutCycleMode() {
    const index = WAVE_OUT_MODES.indexOf(WAVE_OUT_STATE.mode);
    const next = WAVE_OUT_MODES[(index + 1) % WAVE_OUT_MODES.length];
    const result = waveOutSaveConfig({ mode: next });
    if (typeof WAVE_SHIELD_STATE.refreshUi === 'function') { try { WAVE_SHIELD_STATE.refreshUi(); } catch (e) {} }
    return result;
}

function waveOutNote(stats, reason) {
    if (stats) {
        WAVE_OUT_STATE.turns += 1;
        WAVE_OUT_STATE.lastChars = Number(stats.emittedChars || stats.chars || 0) || 0;
        WAVE_OUT_STATE.lastTime = new Date().toLocaleTimeString('zh-CN', { hour12: false });
        WAVE_OUT_STATE.lastMode = stats.plainWon ? '正文（未走通道）' : (stats.textMode ? '文本标记' : '工具参数');
    }
