﻿/* ---------------- 请求整形 ---------------- */
function waveOutSkipReason(body) {
    if (!body || typeof body !== 'object') return '请求体不是对象';
    if (!Array.isArray(body.messages) || !body.messages.length) return '没有对话消息';
    if (body.tool_choice === 'none') return '本轮禁用了工具调用';
    if (body.tool_choice === 'required') return '本轮强制了工具调用';
    if (body.tool_choice && typeof body.tool_choice === 'object') return '本轮固定了某个工具';
    if (body.json_schema) return '本轮指定了结构化输出';
    if (body.response_format && body.response_format.type && body.response_format.type !== 'text') return '本轮指定了结构化输出';
    if (body.enable_web_search || body.use_google_search || body.use_url_context) return '本轮开启了联网或搜索';
    const tools = Array.isArray(body.tools) ? body.tools : [];
    if (tools.some(t => t && t.function && t.function.name === WAVE_OUT_TOOL)) return '请求里已经有同名工具';
    for (const m of body.messages) {
        if (!m || typeof m !== 'object') return '消息格式未知';
        if (m.role === 'tool' || m.tool_call_id) return '历史里有工具结果';
        if (Array.isArray(m.tool_calls) && m.tool_calls.length) return '历史里有工具调用';
        if (m.function_call) return '历史里有工具调用';
    }
    return '';
}

function waveOutTextInstruction() {
    return '【本轮交付方式】把这一轮要交的全部内容（含所有约定标签）写进下面两个标记之间，'
        + '标记之外不要写任何正文、说明或第二份稿子。换行写真实的换行。\n'
        + WAVE_OUT_OPEN + '\n（这里放完整正文）\n' + WAVE_OUT_CLOSE;
}

function waveOutPrepare(body) {
    waveOutReadConfig();
    const mode = WAVE_OUT_STATE.mode;
    if (mode === 'off') return null;
    const skip = waveOutSkipReason(body);
    if (skip) { WAVE_OUT_STATE.skip = skip; return null; }
    const tools = Array.isArray(body.tools) ? body.tools : [];
    const useText = mode === 'text' || (mode === 'auto' && !tools.length);
    try {
        if (!useText) {
            const clientToolNames = collectToolNames(tools);
            body.tools = [...tools, buildToolDefinition(WAVE_OUT_TOOL)];
            body.tool_choice = 'auto';
            const control = buildControlPrompt(WAVE_OUT_TOOL);
            const last = body.messages[body.messages.length - 1];
            if (last && typeof last.content === 'string') last.content = last.content + '\n\n' + control;
            else body.messages.push({ role: 'user', content: control });
            WAVE_OUT_STATE.skip = '';
            return { mode: 'native', toolName: WAVE_OUT_TOOL, clientToolNames, streaming: body.stream === true };
        }
        const last = body.messages[body.messages.length - 1];
        if (last && typeof last.content === 'string') last.content = last.content + '\n\n' + waveOutTextInstruction();
        else body.messages.push({ role: 'user', content: waveOutTextInstruction() });
        WAVE_OUT_STATE.skip = '';
        return { mode: 'text', streaming: body.stream === true, toolName: WAVE_OUT_TOOL, clientToolNames: new Set() };
    } catch (error) {
        WAVE_OUT_STATE.error = describeError(error);
        return null;
    }
}

/* ---------------- 回包还原 ---------------- */
async function waveOutRewrite(response, plan) {
    try {
        if (!response || !response.body) return response;
        if (!response.ok) { WAVE_OUT_STATE.error = 'HTTP ' + response.status + '：接口报错，本轮没有改写'; WAVE_OUT_STATE.skip = 'HTTP ' + response.status + '：接口报错，本轮没有改写'; return response; }
        if (plan.mode === 'text') return await waveOutTextRewrite(response, plan);
        if (plan.streaming) {
            return rewriteEventStream(response, plan.toolName, plan.clientToolNames, stats => waveOutNote(stats, ''));
        }
        const result = await rewriteJsonResponse(response, plan.toolName, plan.clientToolNames);
        if (result && result.recovered) {
            waveOutNote({ emittedChars: result.recovered.chars, plainWon: result.recovered.plainWon }, '');
        }
        return (result && result.response) || response;
    } catch (error) {
        WAVE_OUT_STATE.error = describeError(error);
        return response;
    }
}

function waveOutExtractText(text) {
    const source = String(text || '');
    const open = source.indexOf(WAVE_OUT_OPEN);
    const close = source.lastIndexOf(WAVE_OUT_CLOSE);
    let out = source;
    if (open >= 0 && close > open) out = source.slice(open + WAVE_OUT_OPEN.length, close);
    else if (open >= 0) out = source.slice(open + WAVE_OUT_OPEN.length);
    else if (close >= 0) out = source.slice(0, close);
    return out.replace(/^\s+/, '').replace(/\s+$/, '');
}

function waveOutCollectText(raw, streaming) {
    let text = '';
    const takeParts = parts => {
        if (!Array.isArray(parts)) return;
        for (const part of parts) if (part && typeof part.text === 'string') text += part.text;
    };
    if (streaming) {
        for (const line of String(raw).split('\n')) {
            const trimmed = line.trim();
            if (!trimmed.startsWith('data:')) continue;
            const payload = trimmed.slice(5).trim();
            if (!payload || payload === '[DONE]') continue;
            try {
                const obj = JSON.parse(payload);
                const delta = obj?.choices?.[0]?.delta?.content;
                if (typeof delta === 'string') text += delta;
                takeParts(obj?.candidates?.[0]?.content?.parts);
            } catch (e) {}
        }
        return text;
    }
    try {
        const obj = JSON.parse(raw);
        const content = obj?.choices?.[0]?.message?.content;
        if (typeof content === 'string') text += content;
        takeParts(obj?.candidates?.[0]?.content?.parts);
    } catch (e) {
        text = String(raw || '');
    }
    return text;
}

function waveOutBuildResponse(container, streaming, text) {
    if (streaming) {
        const chunk = {
            candidates: [{ index: 0, content: { role: 'model', parts: [{ text }] } }],
            choices: [{ index: 0, delta: { content: text }, finish_reason: null }],
        };
        const end = {
            candidates: [{ index: 0, content: { role: 'model', parts: [{ text: '' }] }, finishReason: 'STOP' }],
            choices: [{ index: 0, delta: {}, finish_reason: 'stop' }],
        };
        const body = 'data: ' + JSON.stringify(chunk) + '\n\ndata: ' + JSON.stringify(end) + '\n\ndata: [DONE]\n\n';
        return new Response(body, { status: 200, headers: { 'content-type': 'text/event-stream' } });
    }
    const body = JSON.stringify({
        choices: [{ index: 0, message: { role: 'assistant', content: text }, finish_reason: 'stop' }],
        candidates: [{ index: 0, content: { role: 'model', parts: [{ text }] }, finishReason: 'STOP' }],
    });
    return new Response(body, { status: 200, headers: { 'content-type': 'application/json' } });
}

async function waveOutTextRewrite(response, plan) {
    const raw = await response.text();
    const text = waveOutExtractText(waveOutCollectText(raw, plan.streaming));
    waveOutNote({ emittedChars: text.length, textMode: true }, '');
    return waveOutBuildResponse(null, plan.streaming, text);
}

