  const COMMON_CONTENT_KEYS = [
    "content", "actual_content", "text", "output", 
    "response", "reply", "message", "result", "ans", "answer"
  ];
  const HIGH_SURROGATE_START = 55296; // 0xD800
  const HIGH_SURROGATE_END = 56319;   // 0xDBFF
  const LOW_SURROGATE_START = 56320;  // 0xDC00
  const LOW_SURROGATE_END = 57343;    // 0xDFFF
  const MAX_KEY_SCAN = 500;

  const SIMPLE_ESCAPES = {
    '"': '"', "\\": "\\", "/": "/", b: "\b", f: "\f", n: "\n", r: "\r", t: "\t"
  };

  class IncrementalContentDecoder {
    state = "init";
    keyScan = "";
    pendingEscape = "";
    pendingQuote = false;
    highSurrogate = 0;
    emittedAny = false;

    feed(fragment) {
      if (!fragment) return "";
      let out = "";
      let source = fragment;

      if (this.pendingQuote) {
        this.pendingQuote = false;
        const rest = source.replace(/^[\s]*/, "");
        if (rest.startsWith("}") || rest === "") {
          this.state = "completed";
          return "";
        }
        out += '"';
      }

      if (this.pendingEscape) {
        source = this.pendingEscape + source;
        this.pendingEscape = "";
      }

      let i = 0;
      while (i < source.length) {
        const char = source[i];
        switch (this.state) {
          case "init":
            if (char === "{" || char === '"') {
              this.state = "lookingForKey";
              if (char === '"') this.keyScan = '"';
            } else if (!/\s/.test(char)) {
              this.state = "rawText";
              out += char;
            }
            i += 1;
            break;

          case "lookingForKey":
            this.keyScan += char;
            i += 1;
            if (COMMON_CONTENT_KEYS.some((k) => this.keyScan.includes(`"${k}"`)) || /"[\w\-]+"\s*$/.test(this.keyScan)) {
              this.state = "lookingForColon";
              this.keyScan = "";
            } else if (this.keyScan.length > MAX_KEY_SCAN) {
              this.state = "rawText";
            }
            break;

          case "lookingForColon":
            if (char === ":") this.state = "lookingForQuote";
            else if (char === '"') this.state = "inString";
            i += 1;
            break;

          case "lookingForQuote":
            if (char === '"') this.state = "inString";
            else if (!/\s/.test(char)) {
              this.state = "rawText";
              out += char;
            }
            i += 1;
            break;

          case "inString": {
            const consumed = this.consumeStringChar(source, i);
            out += consumed.text;
            if (consumed.stop) i = source.length;
            else i += consumed.width;
            break;
          }

          case "rawText": {
            out += char;
            i += 1;
            break;
          }

          case "completed": {
            const rest = source.slice(i).trim();
            if (rest !== "" && rest !== "}" && rest !== "},") {
              this.state = "inString";
              break;
            }
            i = source.length;
            break;
          }

          case "error":
            this.state = "rawText";
            break;
        }
      }

      if (out) this.emittedAny = true;
      return out;
    }

    consumeStringChar(source, index) {
      const char = source[index];
      if (char === "\\") {
        const next = source[index + 1];
        if (next === undefined) {
          this.pendingEscape = "\\";
          return { text: "", width: 0, stop: true };
        }
        if (next === "u") {
          const hex = source.slice(index + 2, index + 6);
          if (hex.length < 4) {
            this.pendingEscape = source.slice(index);
            return { text: "", width: 0, stop: true };
          }
          const code = Number.parseInt(hex, 16);
          if (Number.isNaN(code)) return { text: `\\u${hex}`, width: 6, stop: false };
          if (code >= HIGH_SURROGATE_START && code <= HIGH_SURROGATE_END) {
            this.highSurrogate = code;
            return { text: "", width: 6, stop: false };
          }
          if (code >= LOW_SURROGATE_START && code <= LOW_SURROGATE_END && this.highSurrogate) {
            const combined = 65536 + ((this.highSurrogate - HIGH_SURROGATE_START) << 10) + (code - LOW_SURROGATE_START);
            this.highSurrogate = 0;
            return { text: String.fromCodePoint(combined), width: 6, stop: false };
          }
          return { text: String.fromCharCode(code), width: 6, stop: false };
        }

        const simple = SIMPLE_ESCAPES[next];
        if (simple !== undefined) return { text: simple, width: 2, stop: false };
        return { text: char + next, width: 2, stop: false };
      }

      if (char === '"') {
        const rest = source.slice(index + 1);
        if (rest === "") {
          this.pendingQuote = true;
          return { text: "", width: 0, stop: true };
        }
        if (rest.replace(/^[\s]*/, "").startsWith("}")) {
          this.state = "completed";
          return { text: "", width: 0, stop: true };
        }
        return { text: '"', width: 1, stop: false };
      }

      return { text: char, width: 1, stop: false };
    }

    finish() {
      let out = "";
      if (this.pendingQuote && !this.emittedAny) out += '"';
      this.pendingQuote = false;
      if (this.pendingEscape) {
        out += this.pendingEscape;
        this.pendingEscape = "";
      }
      if (out) this.emittedAny = true;
      return out;
    }
