  function extractContentFromObject(obj) {
    if (!obj || typeof obj !== "object") return undefined;
    for (const key of COMMON_CONTENT_KEYS) {
      if (typeof obj[key] === "string" && obj[key].length > 0) {
        return obj[key];
      }
    }
    let best = undefined;
    for (const [k, v] of Object.entries(obj)) {
      if (typeof v === "string" && v.length > 0) {
        if (!best || v.length > best.length) best = v;
      } else if (v && typeof v === "object") {
        const nested = extractContentFromObject(v);
        if (nested && (!best || nested.length > best.length)) best = nested;
      }
    }
    return best;
  }

  function readArgsContent(args) {
    if (typeof args === "object" && args !== null) {
      return extractContentFromObject(args);
    }
    if (typeof args === "string") {
      const trimmed = args.trim();
      if (!trimmed) return undefined;

      try {
        const parsed = JSON.parse(trimmed);
        if (typeof parsed === "string") return parsed;
        if (typeof parsed === "object" && parsed !== null) {
          const extracted = extractContentFromObject(parsed);
          if (typeof extracted === "string") return extracted;
        }
      } catch {}

      const cleaned = trimmed.replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "").trim();
      if (cleaned !== trimmed) {
        try {
          const parsed = JSON.parse(cleaned);
          if (typeof parsed === "string") return parsed;
          if (typeof parsed === "object" && parsed !== null) {
