      const decoder = new IncrementalContentDecoder();
      const salvaged = decoder.feed(cleaned) + decoder.finish();
      if (salvaged && salvaged.trim().length > 0) return salvaged;

      const match = cleaned.match(/"(?:content|actual_content|text|output|response|message)"\s*:\s*"((?:[^"\\]|\\.)*)/i);
      if (match && match[1]) {
        try {
          return JSON.parse(`"${match[1]}"`);
