    if (cleanCand === cleanTool || matchesToolName(candidate, toolName) || matchesToolName(candidate, WAVE_OUT_TOOL)) return "own";
    const bare = bareToolName(candidate).toLowerCase();
    if (bare === cleanTool || bare === WAVE_OUT_TOOL.toLowerCase() || bare.includes(cleanTool) || cleanCand.includes(cleanTool)) return "own";
