    // 从 URL 查询参数或路径探测
    if (typeof url === "string" && url) {
      const match = url.match(/(?:models\/|[?&]model=)([^&/?#]+)/i);
      if (match && match[1]) {
        return decodeURIComponent(match[1]);
      }
    }

    return undefined;
  }

  /**
   * 校验当前模型是否为指定的防截断目标模型 gemini-4-argon
   * 支持大小写不敏感，支持连字符与下划线互换，支持带前后缀路径（如 google/gemini-4-argon, models/gemini-4-argon）
   */
  function isGemini4Argon(modelName) {
    if (typeof modelName !== "string" || !modelName.trim()) return false;
    return TARGET_MODEL_REGEX.test(modelName.trim());
  }
  class SseContentRewriter {
    constructor(toolName, clientToolNames = new Set()) {
      this.toolName = toolName;
      this.clientToolNames = clientToolNames;
    }

    states = new Map();
    stats = {
      syntheticSeen: false,
      contentConflict: false,
      plainWon: false,
      sawDone: false,
      decodedChars: 0,
      emittedChars: 0,
      decodedChunks: 0
    };

    lastChunkMeta = {
      id: "chatcmpl-turing",
      model: "unknown",
      created: Math.floor(Date.now() / 1000)
    };

    state(index, dialect) {
      let existing = this.states.get(index);
      if (!existing) {
        existing = {
          dialect,
          plain: "",
          sent: "",
          channels: new Map(),
          slotNames: new Map(),
          activeGoogleChannel: undefined,
          sawSynthetic: false
        };
        this.states.set(index, existing);
      }
      existing.dialect = dialect;
      return existing;
    }

    transformPayload(payload) {
      const trimmed = payload.trim();
      if (trimmed === "[DONE]") {
        this.stats.sawDone = true;
        return payload;
      }
      let chunk;
      try {
        const parsed = JSON.parse(trimmed);
        if (!parsed || typeof parsed !== "object") return payload;
        chunk = parsed;
      } catch {
        return payload;
      }

      if (typeof chunk["id"] === "string") this.lastChunkMeta.id = chunk["id"];
      if (typeof chunk["model"] === "string") this.lastChunkMeta.model = chunk["model"];
      if (typeof chunk["created"] === "number") this.lastChunkMeta.created = chunk["created"];

      const choices = chunk["choices"];
      if (Array.isArray(choices)) return this.rewriteChoices(chunk, choices, payload);

      const candidates = chunk["candidates"];
      if (Array.isArray(candidates)) return this.rewriteCandidates(chunk, candidates, payload);

      return payload;
    }

    rewriteChoices(chunk, choices, payload) {
      let touched = false;
      let anythingToSend = false;

      for (const rawChoice of choices) {
        if (!rawChoice || typeof rawChoice !== "object") continue;
        const choice = rawChoice;
        const index = typeof choice["index"] === "number" ? choice["index"] : 0;
        const state = this.state(index, "openai");
        const field = choice["delta"] === undefined || choice["delta"] === null ? (choice["message"] && typeof choice["message"] === "object" ? "message" : "delta") : "delta";
        const delta = choice[field] ?? {};
        const originalContent = typeof delta["content"] === "string" ? delta["content"] : "";
        let streamedText = "";

        const toolCalls = delta["tool_calls"];
        if (Array.isArray(toolCalls)) {
          const { handled, decoded, remaining } = this.consumeToolCalls(state, toolCalls);
          streamedText += decoded;
          if (handled) touched = true;
          if (remaining.length > 0) {
            delta["tool_calls"] = remaining;
            anythingToSend = true;
          } else if (toolCalls.length > 0 && handled) {
            delete delta["tool_calls"];
            touched = true;
          }
        }

        if (originalContent) {
          if (state.sawSynthetic) {
            touched = true;
            delete delta["content"];
            state.plain += originalContent;
          } else {
            anythingToSend = true;
          }
        }

        if (streamedText) {
          delta["content"] = streamedText;
          anythingToSend = true;
        }

        const finish = choice["finish_reason"];
        if (finish !== null && finish !== undefined) {
          touched = true;
          anythingToSend = true;
          const tail = this.finalizeChoice(state);
          if (tail) {
            delta["content"] = (delta["content"] ?? "") + tail;
          }
          if (state.sawSynthetic && finish === "tool_calls") {
            choice["finish_reason"] = "stop";
          }
          if (delta["content"] === undefined) {
            delta["content"] = "";
          }
        }

        if (Object.keys(delta).length > 0) anythingToSend = true;
        choice[field] = delta;
      }

      if (!touched) return payload;
      if (!anythingToSend) return undefined;
      return JSON.stringify(chunk);
    }

    /** 改写 Google Gemini 格式，并同时注入 OpenAI choices 字段 */
    rewriteCandidates(chunk, candidates, payload) {
      let touched = false;
      let anythingToSend = false;

      for (const rawCandidate of candidates) {
        if (!rawCandidate || typeof rawCandidate !== "object") continue;
        const candidate = rawCandidate;
        const index = typeof candidate["index"] === "number" ? candidate["index"] : 0;
        const state = this.state(index, "google");
        const rawContent = candidate["content"];
        const content = rawContent && typeof rawContent === "object" ? rawContent : {};
        const parts = content["parts"];
        let streamedText = "";
        const kept = [];
        let savedThoughtSig = undefined;

        if (Array.isArray(parts)) {
          for (const rawPart of parts) {
            if (!rawPart || typeof rawPart !== "object") {
              kept.push(rawPart);
              continue;
            }
            const part = rawPart;
            if (part["thoughtSignature"] && !savedThoughtSig) {
              savedThoughtSig = part["thoughtSignature"];
            }
            const call = part["functionCall"];
            if (call && typeof call === "object") {
              const consumed = this.consumeGoogleCall(state, call);
              if (!consumed.handled) {
                kept.push(rawPart);
                continue;
              }
              streamedText += consumed.decoded;
              touched = true;
              continue;
            }
            if (part["thought"] === true) {
              kept.push(rawPart);
              continue;
            }
            if (typeof part["text"] === "string" && part["text"]) {
              if (state.sawSynthetic) {
                touched = true;
                state.plain += part["text"];
                continue;
              } else {
                kept.push(rawPart);
                anythingToSend = true;
                continue;
              }
            }
            kept.push(rawPart);
          }
        }

        let emitted = streamedText;
        const finish = candidate["finishReason"];
        if (finish !== null && finish !== undefined) {
          touched = true;
          anythingToSend = true;
          emitted += this.finalizeChoice(state);
        }

        if (!touched) continue;

        // 规范化 finishReason：当拦截到防截断工具调用时，强制改为 stop，杜绝前端当作工具调用丢弃
        let normalizedFinish = finish ? String(finish).toLowerCase() : null;
        if (state.sawSynthetic && (normalizedFinish === "tool_calls" || normalizedFinish === "stop" || finish !== undefined)) {
          normalizedFinish = "stop";
        }

        // 1. 改写原生 Gemini parts
        const nextParts = [];
        if (emitted) {
          const textPart = { text: emitted };
          if (savedThoughtSig) textPart["thoughtSignature"] = savedThoughtSig;
          nextParts.push(textPart);
        }
        nextParts.push(...kept);

        if (nextParts.length > 0 || Array.isArray(parts)) {
          content["parts"] = nextParts;
          if (typeof content["role"] !== "string") content["role"] = "model";
          candidate["content"] = content;
        }

        // 2. 核心双向兼容：同时为 chunk 注入标准 OpenAI choices 格式！
        // 彻底解决酒馆 chat-completions 端点读不到 choices 导致气泡空回的问题！
        if (emitted || normalizedFinish) {
          if (normalizedFinish) candidate["finishReason"] = normalizedFinish.toUpperCase();
          chunk["choices"] = [
            {
              index,
              delta: { content: emitted || "" },
              finish_reason: normalizedFinish
            }
          ];
          anythingToSend = true;
        }

        if (nextParts.length > 0) anythingToSend = true;
      }

      if (!touched) return payload;
      if (!anythingToSend) return undefined;
      return JSON.stringify(chunk);
    }

    consumeGoogleCall(state, call) {
      const name = call["name"];
      let channelName;
      if (typeof name === "string" && name) {
        if (classifyToolName(name, this.toolName, this.clientToolNames) === "client") {
          state.activeGoogleChannel = undefined;
          return { handled: false, decoded: "" };
        }
        channelName = bareToolName(name);
        state.activeGoogleChannel = channelName;
      } else {
        channelName = state.activeGoogleChannel;
      }

      if (channelName === undefined) {
        if (this.clientToolNames.size === 0) {
          channelName = this.toolName || WAVE_OUT_TOOL;
          state.activeGoogleChannel = channelName;
        } else {
          const empty = call["args"] === undefined && call["partialArgs"] === undefined && state.sawSynthetic;
          return { handled: empty, decoded: "" };
        }
      }

      this.markSynthetic(state);
      const channel = this.channel(state, channelName);
      let text = "";

      const partialArgs = call["partialArgs"];
      if (Array.isArray(partialArgs)) text += readPartialArgs(partialArgs);
      if (call["args"] !== undefined) text += decodeGoogleArgs(channel, call["args"]);

      if (call["willContinue"] !== true) state.activeGoogleChannel = undefined;

      AntiTruncationDebugger.recordToolCall(call, "sse-gemini-call", text);
      return { handled: true, decoded: this.absorb(state, channel, text) };
    }

    markSynthetic(state) {
      if (state.sawSynthetic) return;
      state.sawSynthetic = true;
      this.stats.syntheticSeen = true;
    }

    channel(state, name) {
      let channel = state.channels.get(name);
      if (!channel) {
        channel = { decoder: new IncrementalContentDecoder(), text: "" };
        state.channels.set(name, channel);
      }
      return channel;
    }

    absorb(state, channel, text) {
      if (!text) return "";
      channel.text += text;
      this.stats.decodedChunks += 1;

      // 同步实时吐到悬浮监视器中！
      FloatingMonitor.append(text);

      if (state.plain !== "" || state.channels.size > 1) return "";
      state.sent += text;
      this.stats.decodedChars += text.length;
      this.stats.emittedChars += text.length;
      return text;
    }

    consumeToolCalls(state, toolCalls) {
      let handled = false;
      let decoded = "";
      const remaining = [];

      for (const rawCall of toolCalls) {
        if (!rawCall || typeof rawCall !== "object") {
          remaining.push(rawCall);
          continue;
        }
        const call = rawCall;
        const callIndex = typeof call["index"] === "number" ? call["index"] : 0;
        const fn = call["function"] ?? {};
        const name = typeof fn["name"] === "string" ? fn["name"] : "";

        let channelName = state.slotNames.get(callIndex);
        if (name) {
          const origin = classifyToolName(name, this.toolName, this.clientToolNames);
          if (origin === "client") {
            channelName = undefined;
            state.slotNames.delete(callIndex);
          } else {
            channelName = bareToolName(name);
            state.slotNames.set(callIndex, channelName);
          }
        }

        if (channelName === undefined) {
          if (this.clientToolNames.size === 0) {
            channelName = this.toolName || WAVE_OUT_TOOL;
            state.slotNames.set(callIndex, channelName);
          } else {
            remaining.push(rawCall);
            continue;
          }
        }

        handled = true;
        this.markSynthetic(state);
        const channel = this.channel(state, channelName);
        const args = fn["arguments"];
        if (args !== undefined && args !== null) {
          const rawArgStr = typeof args === "string" ? args : JSON.stringify(args);
          const chunkDecoded = channel.decoder.feed(rawArgStr);
          decoded += this.absorb(state, channel, chunkDecoded);
          AntiTruncationDebugger.recordToolCall(rawCall, "sse-tool_calls", chunkDecoded);
        }
      }

      return { handled, decoded, remaining };
    }

    finalizeChoice(state) {
      let best = "";
      let bestIsPlain = false;
      let contenders = 0;

      for (const channel of state.channels.values()) {
        channel.text += channel.decoder.finish();
        if (channel.text) contenders += 1;
        if (channel.text.length > best.length) {
          best = channel.text;
          bestIsPlain = false;
        }
        channel.text = "";
      }

      if (state.plain) {
        contenders += 1;
        if (state.plain.length > best.length) {
          best = state.plain;
          bestIsPlain = true;
        }
      }
      state.plain = "";

      if (contenders > 1) {
        this.stats.contentConflict = true;
        if (bestIsPlain) this.stats.plainWon = true;
      }

      const tail = best.startsWith(state.sent) ? best.slice(state.sent.length) : best;
      state.sent += tail;
      this.stats.emittedChars += tail.length;
      if (!bestIsPlain) this.stats.decodedChars += tail.length;

      if (tail) FloatingMonitor.append(tail);
      return tail;
    }

    finalizePending() {
      const { id, model, created } = this.lastChunkMeta;
      const payloads = [];

      for (const [index, state] of this.states) {
        const pending = this.finalizeChoice(state);
        if (!pending) continue;

        // 双向输出保护
        payloads.push(
          JSON.stringify({
            id,
            object: "chat.completion.chunk",
            created,
            model,
            choices: [{ index, delta: { content: pending }, finish_reason: null }],
            candidates: [{ index, content: { role: "model", parts: [{ text: pending }] } }]
          })
        );
      }
      return payloads;
    }
  }

  function readPartialArgs(partialArgs) {
    let text = "";
    for (const rawFragment of partialArgs) {
      if (!rawFragment || typeof rawFragment !== "object") continue;
      const fragment = rawFragment;
      const path = typeof fragment["jsonPath"] === "string" ? fragment["jsonPath"].trim() : "";
      if (path === "$.content" || path.includes("content") || path.includes("actual_content")) {
        const value = fragment["stringValue"];
        if (typeof value === "string") text += value;
      }
    }
    return text;
  }

  function decodeGoogleArgs(channel, args) {
    if (typeof args === "string") return args ? channel.decoder.feed(args) : "";
    if (args && typeof args === "object") {
      const content = extractContentFromObject(args);
      if (typeof content !== "string" || !content) return "";
      if (!channel.text) return content;
      if (content.startsWith(channel.text)) return content.slice(channel.text.length);
      if (channel.text.startsWith(content)) return "";
      return content;
    }
    return "";
  }

  // ===================================================================================
  // 8. 响应重写与双向注入 (Stream & JSON Rewriter)
  // ===================================================================================

  function findSseBoundary(buf) {
    const match = /\r\n\r\n|\n\n|\r\r/.exec(buf);
    if (!match) return null;
    return {
      index: match.index,
      length: match[0].length
    };
  }

  function rewriteEventStream(response, toolName, clientToolNames, onComplete) {
    const rewriter = new SseContentRewriter(toolName, clientToolNames);
    const decoder = new TextDecoder();
    const encoder = new TextEncoder();
    let buffer = "";
    let doneEmitted = false;

    // 向下游发送结束信号与 [DONE]
    function emitDone(controller) {
      if (doneEmitted) return;
      doneEmitted = true;

      // 1. 刷出任何 pending 的未发分块
      for (const payload of rewriter.finalizePending()) {
        controller.enqueue(encoder.encode(`data: ${payload}\n\n`));
      }

      // 2. 注入标准 [DONE] 标记，酒馆前端收到后立即结束流式循环并定稿气泡！
      controller.enqueue(encoder.encode("data: [DONE]\n\n"));
      rewriter.stats.sawDone = true;

      // 3. 立即更新监视器状态与统计
      FloatingMonitor.finishSession();
      AntiTruncationDebugger.recordStats(rewriter.stats);
      Logger.info(`流式传输防截断正文已就绪并通知前端定稿 [累计 ${rewriter.stats.emittedChars} 字]`);
      onComplete?.(rewriter.stats);
    }

    const transformStream = new TransformStream({
      transform(chunk, controller) {
        // 若已向下游发送了 [DONE]，上游后续的冗余空分块（如后端的心跳或空候选体）直接静默忽略
        if (doneEmitted) return;

        buffer += decoder.decode(chunk, { stream: true });
        let boundary = findSseBoundary(buffer);

        while (boundary !== null) {
          const rawEvent = buffer.slice(0, boundary.index);
          buffer = buffer.slice(boundary.index + boundary.length);

          if (rawEvent.trim()) {
            AntiTruncationDebugger.recordChunk(rawEvent);
            const rewritten = rewriteEvent(rewriter, rawEvent);
            if (rewritten !== undefined) {
              controller.enqueue(encoder.encode(rewritten + "\n\n"));
            }


          }
          boundary = findSseBoundary(buffer);
        }
      },
      flush(controller) {
        if (buffer.trim() && !doneEmitted) {
          const rest = buffer.trim();
          AntiTruncationDebugger.recordChunk(rest);
          const rewritten = rewriteEvent(rewriter, rest);
          if (rewritten !== undefined) {
            controller.enqueue(encoder.encode(rewritten + "\n\n"));
          }
        }
        emitDone(controller);
      }
    });

    const transformedBody = response.body.pipeThrough(transformStream);

    return new Response(transformedBody, {
      status: response.status,
      statusText: response.statusText,
      headers: response.headers
    });
  }

  function rewriteEvent(rewriter, rawEvent) {
    const lines = rawEvent.split(/\r?\n/);
    const out = [];
    let sawData = false;
    let emittedData = false;

    for (const line of lines) {
      if (!line.startsWith("data:")) {
        out.push(line);
        continue;
      }
      sawData = true;
      const payload = line.slice("data:".length).replace(/^ /, "");
      const rewritten = rewriter.transformPayload(payload);
      if (rewritten !== undefined) {
        out.push(`data: ${rewritten}`);
        emittedData = true;
      }
    }

    if (sawData && !emittedData) return undefined;
    return out.join("\n");
  }

  async function rewriteJsonResponse(response, toolName, clientToolNames) {
    let parsed;
    try {
      parsed = await response.clone().json();
    } catch (error) {
      Logger.warn(`响应非合法 JSON: ${describeError(error)}`);
      return { response, recovered: undefined };
    }

    let recovered;
    try {
      const choices = parsed["choices"];
      if (Array.isArray(choices)) {
        recovered = unwrapOpenAiChoices(choices, toolName, clientToolNames);
      }
      const google = unwrapGoogleContent(parsed, toolName, clientToolNames);
      if (google !== undefined) recovered = mergeRecovery(recovered, google);

      // 非流式双向补全
      if (recovered && recovered.text) {
        FloatingMonitor.set(recovered.text);
        FloatingMonitor.finishSession();
        if (!parsed["choices"] || !Array.isArray(parsed["choices"])) {
          parsed["choices"] = [{ message: { role: "assistant", content: recovered.text }, finish_reason: "stop" }];
        }
      }
    } catch (error) {
      Logger.warn(`解析 JSON 回复失败: ${describeError(error)}`);
      return { response, recovered: undefined };
    }

    if (recovered === undefined) return { response, recovered };

    return {
      response: new Response(JSON.stringify(parsed), {
        status: response.status,
        statusText: response.statusText,
        headers: response.headers
      }),
      recovered
    };
  }

  function mergeRecovery(a, b) {
    if (!a) return b;
    return {
      text: a.text.length >= b.text.length ? a.text : b.text,
      chars: a.chars + b.chars,
      conflict: a.conflict || b.conflict,
      plainWon: a.plainWon || b.plainWon
    };
  }

  function longest(plain, carried) {
    let text = plain;
    let plainWon = true;
    for (const candidate of carried) {
      if (candidate.length >= text.length) {
        text = candidate;
        plainWon = false;
      }
    }
    const contenders = (plain ? 1 : 0) + carried.filter((entry) => entry !== "").length;
    return {
      text,
      chars: text.length,
      conflict: contenders > 1,
      plainWon: plainWon && contenders > 1
    };
  }

  function unwrapOpenAiChoices(choices, toolName, clientToolNames) {
    let recovered;
    for (const rawChoice of choices) {
      const choice = rawChoice;
      const message = choice["message"];
      if (!message) continue;
      const calls = message["tool_calls"];
      if (!Array.isArray(calls)) continue;
      const kept = [];
      const carried = [];

      for (const rawCall of calls) {
        const fn = rawCall?.function;
        const fnName = fn?.name ?? rawCall?.name ?? "";
        if (fn && classifyToolName(fnName, toolName, clientToolNames) !== "client") {
          const value = readArgsContent(fn["arguments"]);
          AntiTruncationDebugger.recordToolCall(rawCall, "json-openAi", value);
          if (typeof value === "string") {
            carried.push(value);
            continue;
          }
        }
        kept.push(rawCall);
      }

      if (carried.length === 0 && calls.length > 0 && clientToolNames.size === 0) {
        for (const rawCall of calls) {
          const fn = rawCall?.function;
          const value = readArgsContent(fn?.arguments);
          if (typeof value === "string" && value.length > 0) {
            carried.push(value);
            AntiTruncationDebugger.recordToolCall(rawCall, "json-openAi-fallback", value);
            break;
          }
        }
      }

      if (carried.length === 0) continue;

      const plain = typeof message["content"] === "string" ? message["content"] : "";
      const best = longest(plain, carried);
      message["content"] = best.text;
      recovered = mergeRecovery(recovered, best);

      if (kept.length > 0) {
        message["tool_calls"] = kept;
      } else {
        delete message["tool_calls"];
        if (choice["finish_reason"] === "tool_calls") choice["finish_reason"] = "stop";
      }
    }
    return recovered;
  }

  function unwrapGoogleContent(parsed, toolName, clientToolNames) {
    const rawContent = parsed["responseContent"] ?? (parsed["candidates"] ? parsed["candidates"][0]?.content : undefined);
    if (!rawContent || typeof rawContent !== "object") return undefined;
    const content = rawContent;
    const parts = content["parts"];
    if (!Array.isArray(parts)) return undefined;

    const kept = [];
    const carried = [];
    let plain = "";
    let signature;

    for (const rawPart of parts) {
      const part = rawPart;
      const call = part?.["functionCall"];
      if (call && classifyToolName(call["name"], toolName, clientToolNames) !== "client") {
        const value = readArgsContent(call["args"]);
        AntiTruncationDebugger.recordToolCall(call, "json-google", value);
        if (typeof value === "string") {
          carried.push(value);
          if (part?.["thoughtSignature"] !== undefined) signature = part["thoughtSignature"];
          continue;
        }
      }
      if (part && part["thought"] !== true && typeof part["text"] === "string" && part["text"]) {
        plain += part["text"];
        if (signature === undefined && part["thoughtSignature"] !== undefined) {
          signature = part["thoughtSignature"];
        }
        continue;
      }
      kept.push(rawPart);
    }

    if (carried.length === 0) return undefined;

    const choices = parsed["choices"];
    const message = Array.isArray(choices) ? choices[0]?.message : undefined;
    const wrapped = typeof message?.["content"] === "string" ? message["content"] : "";
    const best = longest(plain.length >= wrapped.length ? plain : wrapped, carried);

    const textPart = { text: best.text };
    if (signature !== undefined) textPart["thoughtSignature"] = signature;
    content["parts"] = [textPart, ...kept];
    if (message) message["content"] = best.text;

    return best;
  }

  // ===================================================================================
  // 9. 全局 Fetch 拦截器 (AntiTruncationInterceptor)
  // ===================================================================================

  const FETCH_MARKER = "__TuringAntiTruncationFetch__";


function waveHelperBoot() {
    try { startHelperScript(); } catch (error) { console.error('[我即浪潮] 搬运脚本启动异常', error); }
    try { waveShieldAttach(globalThis); } catch (error) { console.error('[浪潮护盾] 启动异常', error); }
}

if (typeof $ === 'function') {
    $(waveHelperBoot);
} else if (typeof document !== 'undefined' && document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', waveHelperBoot, { once: true });
} else {
    waveHelperBoot();
