// Trusted message-iframe code. Model text is read as data, never inserted as HTML.
// API/source baseline: Tavern Helper 4.11.3, e71c990607f6c92127151b1f8dad6c79fa03966e.
function createWavePanelRuntime(config) {
  const tags = {plan:'wave_plan',mind:'wave_mind',options:'wave_options',summary:'wave_summary',review:'wave_review',comment:'wave_comment'};
  // 模型偶尔把换行写成字面的反斜杠加 n，这里先还原成真换行，再交给解析与渲染。
  const waveSquash = (value) => {
