    target.replaceChildren();
    let list=null, listType='';
    for (const line of text.trim().split(/\r?\n/)) {
      if (!line.trim()) {list=null;listType='';continue;}
      const item=/^\s*(?:(\d+)[.)、]\s*|([-+*])\s+)(.*)$/.exec(line);
      if (item) {
        const type=item[1]?'ol':'ul';
        if (!list || listType!==type) {list=doc.createElement(type);listType=type;if(item[1])list.start=Number(item[1]);target.append(list);}
        const li=doc.createElement('li');inline(li,item[3],doc);list.append(li);continue;
      }
      list=null;listType='';
      const heading=/^(#{1,4})\s+(.+)$/.exec(line);
      const node=doc.createElement(heading?'h'+Math.min(heading[1].length+1,5):'p');
      inline(node,heading?heading[2]:line,doc);target.append(node);
    }
    if (!target.childNodes.length) target.textContent='这一项没有文字。';
  }
  function markerKind(html) {
    return /<meta name="wave-panel" content="(plan|mind|options|summary|review|comment)">/.exec(html || '')?.[1] ?? null;
  }
  function getFrameKind(frame) {
