  }
  function occurrence(blockCount) {
    if (blockCount===1) return 0;
    const frame=window.frameElement;
    const floor=frame?.closest('.mes');
    if (!frame || !floor) throw new Error('本楼有多个同类条目，但客户端没有提供可识别的楼层容器；请更新酒馆助手后刷新本楼。');
    const frames=Array.from(floor.querySelectorAll('iframe[id^="TH-message--"]')).filter(el=>getFrameKind(el)===config.kind);
    const index=frames.indexOf(frame);
    if (index<0 || frames.length!==blockCount) throw new Error('同类面板的数量与本楼原文尚未对齐。若刷新后仍出现，请检查是否有其它正则隐藏了部分心声，以及客户端的前端兼容情况。');
