// View preference only; the control lives in the existing panel heading.
function createWaveTheme(view = window, root = document.documentElement) {
  const key = 'wave-ui-theme-v1', eventName = 'wave-ui-theme-change-v1';
  let hub = view;
  try { if (view.parent?.document) hub = view.parent; } catch {}
  const media = view.matchMedia?.('(prefers-color-scheme: dark)');
  const valid = value => ['auto', 'day', 'night'].includes(value);
  let mode = 'auto';
  try { mode = hub.localStorage.getItem(key) || 'auto'; } catch {}
  if (valid(hub.__waveUiThemeV1)) mode = hub.__waveUiThemeV1;
  if (!valid(mode)) mode = 'auto';
  const isNight = () => mode === 'night' || mode === 'auto' && !!media?.matches;
  const paint = () => {
    const night = isNight();
    root.setAttribute('data-wave-theme', night ? 'night' : 'day');
    root.querySelectorAll('[data-wave-theme-toggle]').forEach(button => {
      button.textContent = night ? '☾' : '☀';
      button.setAttribute('aria-pressed', String(night));
      button.title = night ? '当前夜间，点击切换日间' : '当前日间，点击切换夜间';
    });
  };
  const receive = event => { if (valid(event.detail)) { mode = event.detail; paint(); } };
  const toggle = event => {
    const button = event.target.closest?.('[data-wave-theme-toggle]');
    if (!button || !root.contains(button)) return;
    // Cancels the summary's default toggle as well as its click propagation.
    event.preventDefault(); event.stopPropagation();
    mode = isNight() ? 'day' : 'night';
    hub.__waveUiThemeV1 = mode;
    try { hub.localStorage.setItem(key, mode); } catch {}
    hub.dispatchEvent(new hub.CustomEvent(eventName, { detail: mode }));
    paint();
